def scrape_docs(url, output_path, **_extra):
    import json, os, datetime, time, hashlib, base64, urllib.parse, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0174000" if __import__("os").path.isdir("./environment_mix/0174000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _dt_to_ms(a, b):
        if not a or not b:
            return None
        da = _parse_rfc3339(a)
        db = _parse_rfc3339(b)
        if not da or not db:
            return None
        return max(0, int((db - da).total_seconds() * 1000))

    def _gen_id(prefix):
        return f"{prefix}_{base64.urlsafe_b64encode(os.urandom(9)).decode('ascii').rstrip('=')}"

    def _normalize_url(u):
        p = urllib.parse.urlsplit(u)
        scheme = (p.scheme or "").lower()
        if scheme not in ("http", "https"):
            return None, None, None, "invalid_url_scheme"
        if not p.netloc:
            return None, None, None, "invalid_url_host"
        host = p.hostname.lower() if p.hostname else ""
        if not host:
            return None, None, None, "invalid_url_host"
        # Normalize: lowercased host, remove fragment, normalize scheme, keep path/query
        # Remove default ports
        port = p.port
        netloc = host
        if port and not ((scheme == "http" and port == 80) or (scheme == "https" and port == 443)):
            netloc = f"{host}:{port}"
        path = p.path or "/"
        # Collapse repeated slashes in path (best-effort)
        path = re.sub(r"/{2,}", "/", path)
        normalized = urllib.parse.urlunsplit((scheme, netloc, path, p.query or "", ""))
        return normalized, host, scheme, None

    def _validate_output_path(op):
        if not isinstance(op, str):
            return "output_path must be a string"
        if len(op) < 1 or len(op) > 4096:
            return "output_path length must be between 1 and 4096"
        if "\x00" in op:
            return "output_path contains null byte"
        # reject absolute paths and windows drive
        if op.startswith("/") or re.match(r"^[A-Za-z]:[\\/]", op):
            return "output_path must be a relative path"
        # normalize separators to forward slashes for checks
        parts = op.replace("\\", "/").split("/")
        if any(part == ".." for part in parts):
            return "output_path must not contain '..'"
        # prevent empty segments that could lead to traversal tricks like "a//../b"
        if any(part == "" for part in parts):
            return "output_path must not contain empty path segments"
        # basic allowlist: printable minus control chars
        if any(ord(c) < 32 for c in op):
            return "output_path contains control characters"
        return None

    # Request logging (best-effort): look for a requests/audit collection if present; otherwise no-op.
    def _log_request(status, api_key_id=None, workspace_id=None, detail=None, started=None):
        try:
            files = set(os.listdir(_DB)) if os.path.isdir(_DB) else set()
        except Exception:
            files = set()
        log_file = None
        for cand in ("request_logs.json", "requests.json", "audit_logs.json", "usage_logs.json"):
            if cand in files:
                log_file = cand
                break
        if not log_file:
            return
        logs = _load(log_file)
        if not isinstance(logs, list):
            logs = []
        now = _now_iso()
        latency_ms = None
        if started is not None:
            latency_ms = int((time.time() - started) * 1000)
        row = {
            "id": _gen_id("req"),
            "endpoint": "scrape_docs",
            "status": status,
            "timestamp": now,
            "latency_ms": latency_ms,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save(log_file, logs)

    t0 = time.time()

    # Validate inputs
    if not isinstance(url, str) or not url:
        _log_request("error", detail="validation_error:url", started=t0)
        return _err("VALIDATION_ERROR", "url is required and must be a non-empty string", field="url")
    if not isinstance(output_path, str) or not output_path:
        _log_request("error", detail="validation_error:output_path", started=t0)
        return _err("VALIDATION_ERROR", "output_path is required and must be a non-empty string", field="output_path")
    if len(url) < 1 or len(url) > 2048:
        _log_request("error", detail="validation_error:url_length", started=t0)
        return _err("VALIDATION_ERROR", "url length must be between 1 and 2048", field="url")
    op_err = _validate_output_path(output_path)
    if op_err:
        _log_request("error", detail="validation_error:output_path_safety", started=t0)
        return _err("CONFLICT", op_err, field="output_path")

    normalized_url, url_host, url_scheme, nerr = _normalize_url(url)
    if nerr:
        _log_request("error", detail=f"validation_error:{nerr}", started=t0)
        return _err("VALIDATION_ERROR", "url must be a valid absolute http(s) URL", field="url", reason=nerr)
    if len(url_host) < 1 or len(url_host) > 255:
        _log_request("error", detail="validation_error:url_host_length", started=t0)
        return _err("VALIDATION_ERROR", "url host length must be between 1 and 255", field="url")

    # Ambient auth: choose any active api key whose workspace is active and usable
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    jobs = _load("scrape_jobs.json")
    artifacts = _load("markdown_artifacts.json")

    ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and w.get("id")}
    key_candidates = []
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        ws = ws_by_id.get(k.get("workspace_id"))
        if not ws:
            continue
        if ws.get("status") != "active":
            continue
        key_candidates.append((ws, k))
    # Also allow "internal" workspace context with no key if any active workspace exists.
    internal_ws = None
    for ws in workspaces:
        if isinstance(ws, dict) and ws.get("status") == "active" and ws.get("id"):
            internal_ws = ws
            break

    if not key_candidates and not internal_ws:
        _log_request("error", detail="unauthorized:no_active_workspace_or_key", started=t0)
        return _err("UNAUTHORIZED", "No active workspace/api key available to perform this operation")

    # Prefer an authenticated key when possible
    if key_candidates:
        workspace, api_key = key_candidates[0]
        api_key_id = api_key.get("id")
    else:
        workspace, api_key, api_key_id = internal_ws, None, None

    # Workspace status rule
    if workspace.get("status") in ("suspended", "deleted"):
        _log_request("error", api_key_id=api_key_id, workspace_id=workspace.get("id"), detail="workspace_not_active", started=t0)
        return _err("CONFLICT", "Workspace is not allowed to create new scrape jobs in its current status", workspace_status=workspace.get("status"))

    # Dedup window: same workspace_id + normalized_url + requested_output_path on same UTC date
    now = datetime.datetime.now(datetime.timezone.utc)
    today = now.date()

    def _job_date(job):
        ca = job.get("created_at")
        dt = _parse_rfc3339(ca) if isinstance(ca, str) else None
        return dt.date() if dt else None

    existing = None
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("workspace_id") != workspace.get("id"):
            continue
        if j.get("normalized_url") != normalized_url:
            continue
        if j.get("requested_output_path") != output_path:
            continue
        if _job_date(j) != today:
            continue
        if j.get("status") in ("queued", "running", "succeeded"):
            existing = j
            break

    # If succeeded, return artifact too
    def _artifact_for_job(job_id):
        for a in artifacts:
            if isinstance(a, dict) and a.get("job_id") == job_id:
                return a
        return None

    # Update key last_used_at if we have one
    if api_key:
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_id:
                k["last_used_at"] = _now_iso()
                k["updated_at"] = _now_iso()
                break
        _save("api_keys.json", api_keys)

    if existing:
        art = _artifact_for_job(existing.get("id"))
        resp = {
            "job": existing,
            "artifact": art,
            "reused": True,
        }
        _log_request("ok", api_key_id=api_key_id, workspace_id=workspace.get("id"), detail="dedupe_reuse", started=t0)
        return resp

    # Create new job in queued, then execute synchronously -> running -> succeeded with local_fs artifact
    now_iso = _now_iso()
    job_id = _gen_id("job")
    job = {
        "id": job_id,
        "workspace_id": workspace.get("id"),
        "api_key_id": api_key_id,
        "url": url,
        "requested_output_path": output_path,
        "normalized_url": normalized_url,
        "url_host": url_host,
        "url_scheme": url_scheme,
        "status": "queued",
        "attempt": 0,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "duration_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    jobs.append(job)
    _save("scrape_jobs.json", jobs)

    # Transition queued -> running
    job["status"] = "running"
    job["started_at"] = _now_iso()
    job["updated_at"] = _now_iso()
    _save("scrape_jobs.json", jobs)

    # "Execute scrape" offline: store deterministic markdown stub; ensure output is sandboxed under workspace
    # Resolved output path: prefix with workspace folder deterministically
    resolved_output_path = output_path  # stored in artifact.output_path
    safe_base = os.path.join(_DB, "artifacts", workspace.get("id"))
    try:
        os.makedirs(safe_base, exist_ok=True)
    except Exception:
        # If we can't create dirs, fail the job
        job["status"] = "failed"
        job["error_code"] = "storage_error"
        job["error_message"] = "Unable to initialize artifact storage"
        job["finished_at"] = _now_iso()
        job["duration_ms"] = _dt_to_ms(job.get("started_at"), job.get("finished_at"))
        job["updated_at"] = _now_iso()
        _save("scrape_jobs.json", jobs)
        _log_request("error", api_key_id=api_key_id, workspace_id=workspace.get("id"), detail="storage_error", started=t0)
        return {"job": job, "artifact": None}

    # Map output_path to a local file inside sandbox without allowing escapes
    # Create a stable filename from output_path to avoid filesystem quirks
    fname = hashlib.sha256((resolved_output_path).encode("utf-8")).hexdigest()[:32] + ".md"
    storage_uri = os.path.join(safe_base, fname)

    # Generate markdown content (offline, deterministic)
    md_title = f"Scraped: {url_host}"
    md = f"# {md_title}\n\nSource: {url}\n\n(Offline scrape simulator)\n"
    md_bytes = md.encode("utf-8")
    sha = hashlib.sha256(md_bytes).hexdigest()

    # Write and verify integrity at write time
    try:
        with open(storage_uri, "wb") as f:
            f.write(md_bytes)
        with open(storage_uri, "rb") as f:
            check = f.read()
    except Exception:
        job["status"] = "failed"
        job["error_code"] = "storage_error"
        job["error_message"] = "Unable to write artifact content"
        job["finished_at"] = _now_iso()
        job["duration_ms"] = _dt_to_ms(job.get("started_at"), job.get("finished_at"))
        job["updated_at"] = _now_iso()
        _save("scrape_jobs.json", jobs)
        _log_request("error", api_key_id=api_key_id, workspace_id=workspace.get("id"), detail="storage_write_error", started=t0)
        return {"job": job, "artifact": None}

    if hashlib.sha256(check).hexdigest() != sha:
        job["status"] = "failed"
        job["error_code"] = "integrity_check_failed"
        job["error_message"] = "Stored markdown failed integrity verification"
        job["finished_at"] = _now_iso()
        job["duration_ms"] = _dt_to_ms(job.get("started_at"), job.get("finished_at"))
        job["updated_at"] = _now_iso()
        _save("scrape_jobs.json", jobs)
        _log_request("error", api_key_id=api_key_id, workspace_id=workspace.get("id"), detail="integrity_failed", started=t0)
        return {"job": job, "artifact": None}

    # Enforce "one artifact per successful job": ensure none exists
    if _artifact_for_job(job_id) is not None:
        job["status"] = "failed"
        job["error_code"] = "artifact_conflict"
        job["error_message"] = "Artifact already exists for this job"
        job["finished_at"] = _now_iso()
        job["duration_ms"] = _dt_to_ms(job.get("started_at"), job.get("finished_at"))
        job["updated_at"] = _now_iso()
        _save("scrape_jobs.json", jobs)
        _log_request("error", api_key_id=api_key_id, workspace_id=workspace.get("id"), detail="artifact_conflict", started=t0)
        return {"job": job, "artifact": None}

    art_id = _gen_id("md")
    fetched_at = _now_iso()
    artifact = {
        "id": art_id,
        "workspace_id": workspace.get("id"),
        "job_id": job_id,
        "output_path": resolved_output_path,
        "storage_backend": "local_fs",
        "storage_uri": storage_uri,
        "content_sha256": sha,
        "content_bytes": len(md_bytes),
        "markdown_title": md_title,
        "source_content_type": "text/html",
        "http_status": 200,
        "fetched_at": fetched_at,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    artifacts.append(artifact)
    _save("markdown_artifacts.json", artifacts)

    # Transition running -> succeeded
    job["status"] = "succeeded"
    job["error_code"] = None
    job["error_message"] = None
    job["finished_at"] = _now_iso()
    job["duration_ms"] = _dt_to_ms(job.get("started_at"), job.get("finished_at"))
    job["updated_at"] = _now_iso()
    _save("scrape_jobs.json", jobs)

    _log_request("ok", api_key_id=api_key_id, workspace_id=workspace.get("id"), detail="created_and_succeeded", started=t0)
    return {"job": job, "artifact": artifact, "reused": False}

def list_scrape_jobs(status=None, url_host=None, normalized_url=None, requested_output_path=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0174000" if __import__("os").path.isdir("./environment_mix/0174000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log_request(status_s, api_key_id=None, workspace_id=None, detail=None, started=None):
        try:
            files = set(os.listdir(_DB)) if os.path.isdir(_DB) else set()
        except Exception:
            files = set()
        log_file = None
        for cand in ("request_logs.json", "requests.json", "audit_logs.json", "usage_logs.json"):
            if cand in files:
                log_file = cand
                break
        if not log_file:
            return
        logs = _load(log_file)
        if not isinstance(logs, list):
            logs = []
        latency_ms = None
        if started is not None:
            latency_ms = int((time.time() - started) * 1000)
        row = {
            "id": f"req_{base64.urlsafe_b64encode(os.urandom(9)).decode('ascii').rstrip('=')}",
            "endpoint": "list_scrape_jobs",
            "status": status_s,
            "timestamp": _now_iso(),
            "latency_ms": latency_ms,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save(log_file, logs)

    t0 = time.time()

    # Validate inputs
    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log_request("error", detail="validation_error:status", started=t0)
        return _err("VALIDATION_ERROR", "Invalid status filter", field="status")
    if url_host is not None and not isinstance(url_host, str):
        _log_request("error", detail="validation_error:url_host", started=t0)
        return _err("VALIDATION_ERROR", "url_host must be a string", field="url_host")
    if normalized_url is not None and not isinstance(normalized_url, str):
        _log_request("error", detail="validation_error:normalized_url", started=t0)
        return _err("VALIDATION_ERROR", "normalized_url must be a string", field="normalized_url")
    if requested_output_path is not None and not isinstance(requested_output_path, str):
        _log_request("error", detail="validation_error:requested_output_path", started=t0)
        return _err("VALIDATION_ERROR", "requested_output_path must be a string", field="requested_output_path")
    if limit is None:
        limit_v = 50
    else:
        if not isinstance(limit, int):
            _log_request("error", detail="validation_error:limit_type", started=t0)
            return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
        if limit < 1 or limit > 200:
            _log_request("error", detail="validation_error:limit_range", started=t0)
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")
        limit_v = limit

    ca_dt = _parse_rfc3339(created_after) if created_after is not None else None
    if created_after is not None and ca_dt is None:
        _log_request("error", detail="validation_error:created_after", started=t0)
        return _err("VALIDATION_ERROR", "created_after must be an RFC 3339 timestamp", field="created_after")
    cb_dt = _parse_rfc3339(created_before) if created_before is not None else None
    if created_before is not None and cb_dt is None:
        _log_request("error", detail="validation_error:created_before", started=t0)
        return _err("VALIDATION_ERROR", "created_before must be an RFC 3339 timestamp", field="created_before")

    # Ambient auth resolution: require an active key + active workspace to exist, else UNAUTHORIZED
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and w.get("id")}
    chosen = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        ws = ws_by_id.get(k.get("workspace_id"))
        if not ws or ws.get("status") != "active":
            continue
        chosen = (ws, k)
        break
    if not chosen:
        _log_request("error", detail="unauthorized:no_active_key", started=t0)
        return _err("UNAUTHORIZED", "API key is invalid or revoked")

    workspace, api_key = chosen
    workspace_id = workspace.get("id")
    api_key_id = api_key.get("id")

    # Pagination cursor: base64(json({"created_at": "...", "id": "..."}))
    start_after = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log_request("error", api_key_id=api_key_id, workspace_id=workspace_id, detail="validation_error:cursor", started=t0)
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string", field="cursor")
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("ascii")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "created_at" not in obj or "id" not in obj:
                raise ValueError("bad cursor")
            start_after = (obj["created_at"], obj["id"])
        except Exception:
            _log_request("error", api_key_id=api_key_id, workspace_id=workspace_id, detail="validation_error:cursor_decode", started=t0)
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    jobs = _load("scrape_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    def _job_dt(j):
        dt = _parse_rfc3339(j.get("created_at")) if isinstance(j, dict) else None
        return dt

    # Filter
    out = []
    for j in jobs:
        if not isinstance(j, dict):
            continue
        if j.get("workspace_id") != workspace_id:
            continue
        if status is not None and j.get("status") != status:
            continue
        if url_host is not None and j.get("url_host") != url_host:
            continue
        if normalized_url is not None and j.get("normalized_url") != normalized_url:
            continue
        if requested_output_path is not None and j.get("requested_output_path") != requested_output_path:
            continue
        dt = _job_dt(j)
        if ca_dt is not None and (dt is None or dt <= ca_dt):
            continue
        if cb_dt is not None and (dt is None or dt >= cb_dt):
            continue
        out.append(j)

    # Sort created_at desc, tie-breaker id desc
    def _sort_key(j):
        dt = _job_dt(j)
        ts = dt.timestamp() if dt else 0.0
        return (ts, str(j.get("id") or ""))

    out.sort(key=_sort_key, reverse=True)

    # Apply cursor: return items strictly "before" the cursor in this sort order
    if start_after is not None:
        ca, jid = start_after
        ca_dt2 = _parse_rfc3339(ca)
        if ca_dt2 is None:
            _log_request("error", api_key_id=api_key_id, workspace_id=workspace_id, detail="validation_error:cursor_created_at", started=t0)
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        filtered = []
        for j in out:
            dt = _job_dt(j)
            if not dt:
                continue
            # Since sorted desc, we want those with (created_at,id) < (cursor_created_at,cursor_id)
            if dt < ca_dt2:
                filtered.append(j)
            elif dt == ca_dt2 and str(j.get("id") or "") < str(jid):
                filtered.append(j)
        out = filtered

    page = out[:limit_v]
    has_more = len(out) > len(page)
    next_cursor = None
    if page:
        last = page[-1]
        payload = {"created_at": last.get("created_at"), "id": last.get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("ascii").rstrip("=")

    _log_request("ok", api_key_id=api_key_id, workspace_id=workspace_id, detail="listed", started=t0)
    return {
        "data": page,
        "meta": {
            "limit": limit_v,
            "total": len(out) if cursor is None else None,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def get_scrape_job(job_id, **_extra):
