def retry_scrape_job(job_id, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0174000" if __import__("os").path.isdir("./environment_mix/0174000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _dt_to_ms(a, b):
        if not a or not b:
            return None
        da = _parse_rfc3339(a)
        db = _parse_rfc3339(b)
        if not da or not db:
            return None
        return max(0, int((db - da).total_seconds() * 1000))

    def _log_request(status_s, api_key_id=None, workspace_id=None, detail=None, started=None):
        try:
            files = set(os.listdir(_DB)) if os.path.isdir(_DB) else set()
        except Exception:
            files = set()
        log_file = None
        for cand in ("request_logs.json", "requests.json", "audit_logs.json", "usage_logs.json"):
            if cand in files:
                log_file = cand
                break
        if not log_file:
            return
        logs = _load(log_file)
        if not isinstance(logs, list):
            logs = []
        latency_ms = None
        if started is not None:
            latency_ms = int((time.time() - started) * 1000)
        row = {
            "id": f"req_{base64.urlsafe_b64encode(os.urandom(9)).decode('ascii').rstrip('=')}",
            "endpoint": "retry_scrape_job",
            "status": status_s,
            "timestamp": _now_iso(),
            "latency_ms": latency_ms,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
        }
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save(log_file, logs)

    t0 = time.time()

    if not isinstance(job_id, str) or not job_id:
        _log_request("error", detail="validation_error:job_id", started=t0)
        return _err("VALIDATION_ERROR", "job_id is required and must be a non-empty string", field="job_id")

    # Ambient auth: choose an active key + active workspace
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and w.get("id")}
    chosen = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        ws = ws_by_id.get(k.get("workspace_id"))
        if not ws or ws.get("id") is None:
            continue
        chosen = (ws, k)
        break
    if not chosen:
        _log_request("error", detail="unauthorized:no_active_key", started=t0)
        return _err("UNAUTHORIZED", "API key is invalid or revoked")

    workspace, api_key = chosen
    workspace_id = workspace.get("id")
    api_key_id = api_key.get("id")

    # Workspace must not be suspended/deleted to retry
    if workspace.get("status") in ("suspended", "deleted"):
        _log_request("error", api_key_id=api_key_id, workspace_id=workspace_id, detail="workspace_not_active", started=t0)
        return _err("CONFLICT", "Workspace is not allowed to retry scrape jobs in its current status", workspace_status=workspace.get("status"))

    jobs = _load("scrape_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    job = None
    for j in jobs:
        if isinstance(j, dict) and j.get("id") == job_id and j.get("workspace_id") == workspace_id:
            job = j
            break
    if not job:
        _log_request("error", api_key_id=api_key_id, workspace_id=workspace_id, detail="not_found", started=t0)
        return _err("NOT_FOUND", "Scrape job not found in workspace", job_id=job_id)

    if job.get("status") != "failed":
        _log_request("error", api_key_id=api_key_id, workspace_id=workspace_id, detail="conflict:not_failed", started=t0)
        return _err("CONFLICT", "Only failed jobs can be retried", current_status=job.get("status"))

    # Enforce transition failed -> queued and increment attempt by 1
    attempt = job.get("attempt")
    if not isinstance(attempt, int) or attempt < 0:
        _log_request("error", api_key_id=api_key_id, workspace_id=workspace_id, detail="validation_error:attempt", started=t0)
        return _err("VALIDATION_ERROR", "Job attempt counter is invalid", field="attempt")

    job["status"] = "queued"
    job["attempt"] = attempt + 1
    job["error_code"] = None
    job["error_message"] = None
    # Clear timing for new run
    job["started_at"] = None
    job["finished_at"] = None
    job["duration_ms"] = None
    job["updated_at"] = _now_iso()

    _save("scrape_jobs.json", jobs)

    _log_request("ok", api_key_id=api_key_id, workspace_id=workspace_id, detail="retried", started=t0)
    return {"job": job}

def cancel_scrape_job(job_id, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0174000" if __import__("os").path.isdir("./environment_mix/0174000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _now_iso():
        return _now().isoformat() + "Z"

    def _parse_dt(val):
        if val is None:
            return None
        if isinstance(val, datetime.datetime):
            return val
        if not isinstance(val, str) or not val.strip():
            return None
        s = val.strip()
        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _dt_to_iso(val):
        if val is None:
            return None
        if isinstance(val, datetime.datetime):
            return val.replace(microsecond=0).isoformat() + "Z"
        if isinstance(val, str):
            return val
        return None

    def _ms(a, b):
        if not a or not b:
            return None
        try:
            return int(max(0, (b - a).total_seconds() * 1000))
        except Exception:
            return None

    def _new_id(prefix):
        # time-sortable enough for this local store
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}"

    def _log(request_logs, *, status, workspace_id=None, api_key_id=None, error_code=None):
        if not isinstance(request_logs, list):
            return
        latency_ms = int(max(0, (datetime.datetime.utcnow() - t0).total_seconds() * 1000))
        row = {
            "id": _new_id("rl"),
            "endpoint": "cancel_scrape_job",
            "timestamp": _now_iso(),
            "status": status,
            "latency_ms": latency_ms,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
        }
        if error_code:
            row["error_code"] = error_code
        request_logs.append(row)
        _save("request_logs.json", request_logs)

    # Load collections
    jobs = _load("scrape_jobs.json")
    artifacts = _load("markdown_artifacts.json")
    request_logs = _load("request_logs.json")

    # Validate inputs
    if not isinstance(job_id, str) or not job_id.strip():
        _log(request_logs, status="error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "job_id must be a non-empty string.", job_id=job_id)

    # Find job
    if not isinstance(jobs, list):
        jobs = []
    job = None
    job_idx = None
    for i, j in enumerate(jobs):
        if isinstance(j, dict) and j.get("id") == job_id:
            job = j
            job_idx = i
            break
    if job is None:
        _log(request_logs, status="error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Scrape job not found.", job_id=job_id)

    # Enforce business rules / lifecycle
    status = job.get("status")
    # Tool contract: refuse already terminal jobs with CONFLICT (not INVALID_TRANSITION)
    if status in ("succeeded", "failed", "cancelled"):
        _log(request_logs, status="error", workspace_id=job.get("workspace_id"), api_key_id=job.get("api_key_id"), error_code="CONFLICT")
        return _err(
            "CONFLICT",
            "Job is already in a terminal state and cannot be cancelled (rule: cancellation only allowed for queued or running jobs).",
            job_id=job_id,
            status=status
        )
    if status not in ("queued", "running"):
        # Unknown/invalid stored status: treat as invalid transition
        _log(request_logs, status="error", workspace_id=job.get("workspace_id"), api_key_id=job.get("api_key_id"), error_code="INVALID_TRANSITION")
        return _err(
            "INVALID_TRANSITION",
            "Illegal job status transition (rule: cancellation only allowed from queued or running).",
            job_id=job_id,
            status=status
        )

    # If running, enforce artifact rule: running job should not already have a final artifact; but don't block cancel if store is inconsistent.
    if isinstance(artifacts, list):
        for a in artifacts:
            if isinstance(a, dict) and a.get("job_id") == job_id:
                # Store inconsistency; cancellation still proceeds, but record reason on job.
                job["error_code"] = job.get("error_code") or "inconsistent_state"
                job["error_message"] = job.get("error_message") or "Warning: artifact existed before cancellation; store may be inconsistent."
                break

    # Apply cancellation
    now = _now()
    job["status"] = "cancelled"
    # if started_at missing but status was running, set started_at to now for coherent duration bookkeeping
    started = _parse_dt(job.get("started_at"))
    if status == "running" and started is None:
        started = now
        job["started_at"] = _dt_to_iso(started)

    job["finished_at"] = _dt_to_iso(now)
    if started is not None:
        job["duration_ms"] = _ms(started, now)
    else:
        job["duration_ms"] = None

    # Preserve/annotate error info for cancellation
    if not job.get("error_code"):
        job["error_code"] = "user_cancelled"
    if not job.get("error_message"):
        job["error_message"] = "Cancelled by client."

    job["updated_at"] = _dt_to_iso(now)

    # Persist mutation
    jobs[job_idx] = job
    _save("scrape_jobs.json", jobs)

    _log(request_logs, status="success", workspace_id=job.get("workspace_id"), api_key_id=job.get("api_key_id"))

    return {"job": job}

def get_markdown_artifact(job_id, include_content=True, **_extra):
    import json, os, datetime, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0174000" if __import__("os").path.isdir("./environment_mix/0174000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    jobs = _load("scrape_jobs.json")
    artifacts = _load("markdown_artifacts.json")
    request_logs = _load("request_logs.json")
    usage = _load("usage.json")

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, workspace_id=None, api_key_id=None, error_code=None):
        ts = _now_iso()
        latency_ms = int(max(0, (datetime.datetime.utcnow() - t0).total_seconds() * 1000))
        if isinstance(request_logs, list):
            request_logs.append({
                "id": f"rl_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
                "endpoint": endpoint,
                "timestamp": ts,
                "status": status,
                "latency_ms": latency_ms,
                "workspace_id": workspace_id,
                "api_key_id": api_key_id,
                "error_code": error_code
            })
            _save("request_logs.json", request_logs)
        if isinstance(usage, list):
            if workspace_id:
                row = None
                for u in usage:
                    if isinstance(u, dict) and u.get("workspace_id") == workspace_id:
                        row = u
                        break
                if row is None:
                    row = {"workspace_id": workspace_id}
                    usage.append(row)
                row["updated_at"] = ts
                row["requests_total"] = int(row.get("requests_total") or 0) + 1
                _save("usage.json", usage)

    # Validate inputs
    if not isinstance(job_id, str) or not job_id.strip():
        _log("get_markdown_artifact", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "job_id must be a non-empty string")
    if include_content is None:
        include_content = True
    if not isinstance(include_content, bool):
        _log("get_markdown_artifact", "error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_content must be a boolean")

    # Resolve job and workspace
    job = None
    for j in jobs:
        if isinstance(j, dict) and j.get("id") == job_id:
            job = j
            break
    if job is None:
        _log("get_markdown_artifact", "error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Scrape job not found", job_id=job_id)

    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == job.get("workspace_id"):
            ws = w
            break
    if ws is None or ws.get("status") == "deleted":
        _log("get_markdown_artifact", "error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized workspace context could be resolved for this job")

    # Find artifact
    artifact = None
    for a in artifacts:
        if isinstance(a, dict) and a.get("job_id") == job_id and a.get("workspace_id") == ws.get("id"):
            artifact = a
            break

    if artifact is None:
        # Refuse NOT_FOUND when no artifact (failed/cancelled/nonexistent)
        _log("get_markdown_artifact", "error", workspace_id=ws.get("id"), api_key_id=job.get("api_key_id"), error_code="NOT_FOUND")
        return _err("NOT_FOUND", "No markdown artifact found for this job", job_id=job_id)

    # Business rule consistency: succeeded must have exactly one artifact; failed/cancelled must have none.
    if job.get("status") in ("failed", "cancelled"):
        _log("get_markdown_artifact", "error", workspace_id=ws.get("id"), api_key_id=job.get("api_key_id"), error_code="CONFLICT")
        return _err("CONFLICT", f"Job is '{job.get('status')}' and must not have a markdown artifact", job_id=job_id)

    # Load content if requested
    content = None
    if include_content:
        backend = artifact.get("storage_backend")
        uri = artifact.get("storage_uri")
        if backend == "local_fs":
            # Treat storage_uri as filesystem path
            try:
                with open(uri, "rb") as f:
                    blob = f.read()
            except FileNotFoundError:
                _log("get_markdown_artifact", "error", workspace_id=ws.get("id"), api_key_id=job.get("api_key_id"), error_code="NOT_FOUND")
                return _err("NOT_FOUND", "Stored markdown content not found", storage_uri=uri)
            except OSError as e:
                _log("get_markdown_artifact", "error", workspace_id=ws.get("id"), api_key_id=job.get("api_key_id"), error_code="CONFLICT")
                return _err("CONFLICT", "Could not read stored markdown content", storage_uri=uri, details=str(e))

            # Integrity check: sha256 must match bytes
            sha = hashlib.sha256(blob).hexdigest()
            if not isinstance(artifact.get("content_sha256"), str) or sha != artifact.get("content_sha256"):
                _log("get_markdown_artifact", "error", workspace_id=ws.get("id"), api_key_id=job.get("api_key_id"), error_code="CONFLICT")
                return _err("CONFLICT", "Artifact integrity check failed (sha256 mismatch)", expected=artifact.get("content_sha256"), actual=sha)

            # Return text (best-effort utf-8); also provide bytes length metadata remains in artifact
            try:
                content = blob.decode("utf-8")
            except UnicodeDecodeError:
                # Return latin-1 fallback to preserve bytes deterministically
                content = blob.decode("latin-1")
        elif backend in ("s3", "gcs"):
            # Offline store cannot fetch; return metadata only even if asked
            content = None
        elif backend == "db_blob":
            # Some stores may embed content directly in storage_uri or elsewhere; here we don't fabricate.
            content = None
        else:
            _log("get_markdown_artifact", "error", workspace_id=ws.get("id"), api_key_id=job.get("api_key_id"), error_code="CONFLICT")
            return _err("CONFLICT", "Unknown storage backend", storage_backend=backend)

    # Update last_used_at if api_key_id exists (read access semantics)
    akid = job.get("api_key_id")
    now_iso = _now_iso()
    if akid:
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == akid:
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                _save("api_keys.json", api_keys)
                break

    _log("get_markdown_artifact", "ok", workspace_id=ws.get("id"), api_key_id=akid)
    resp = {"artifact": artifact}
    if include_content:
        resp["content"] = content
        resp["content_included"] = content is not None
    return resp
